create table public.store_settings(id bigint primary key default 1,store_name text not null default 'FLASH STORE',tagline text default 'Gaming & Digital Store',whatsapp text default '',discord text default '',instapay text default '',telda text default '',vodafone_cash text default '',currency text default 'EGP',announcement text default '⚡ FLASH STORE',hero_title text default 'FLASH STORE',hero_text text default 'Gaming & digital products.',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.categories(id bigint generated by default as identity primary key,name text not null,description text default '',image text default '',active boolean default true,show_on_home boolean default true,sort_order int default 0,created_at timestamptz default now());
create table public.products(id bigint generated by default as identity primary key,name text not null,price numeric(12,2) default 0,category text default 'Other',description text default '',image text default '',emoji text default '🎮',active boolean default true,discount_active boolean default false,discount_type text default 'percent',discount_value numeric(12,2) default 0,options jsonb default '[]'::jsonb,show_on_discounts boolean default false,show_on_flash boolean default false,show_on_best_sellers boolean default false,sales_count int default 0,created_at timestamptz default now());
create table public.users(id bigint generated by default as identity primary key,email text unique not null,name text not null,phone text not null,password_hash text not null,password_salt text not null,status text default 'active',created_at timestamptz default now());
create table public.discounts(id bigint generated by default as identity primary key,code text unique not null,type text default 'percent',value numeric(12,2) default 0,min_total numeric(12,2) default 0,active boolean default true,first_order_only boolean default false,max_uses int default 0,used_count int default 0,created_at timestamptz default now());
create table public.orders(id bigint generated by default as identity primary key,order_number bigint unique not null,name text not null,phone text not null,discord text not null,payment text not null,items jsonb default '[]'::jsonb,subtotal numeric(12,2) default 0,discount numeric(12,2) default 0,total numeric(12,2) default 0,coupon text default '',user_id bigint,user_email text default '',status text default 'new',created_at timestamptz default now());
create table public.discount_usages(id bigint generated by default as identity primary key,discount_id bigint references public.discounts(id) on delete cascade,user_id bigint references public.users(id) on delete cascade,order_id bigint references public.orders(id) on delete set null,used_at timestamptz default now(),unique(discount_id,user_id));
